const fs = require('fs');
const path = require('path');
const outDir = 'C:/dev/deepseek-harness/.gm/scratch';
fs.mkdirSync(outDir, {recursive:true});

const instrSrc = 'C:/dev/deepseek-harness/.gm/exec-spool/out/instruction-gmH2-1-1788727045965-3.json';
const j = JSON.parse(fs.readFileSync(instrSrc, 'utf8'));
const d = j.data || j;
fs.writeFileSync(path.join(outDir, 'instruction.md'), d.instruction || '');
fs.writeFileSync(path.join(outDir, 'prd.yml'), fs.readFileSync('C:/dev/deepseek-harness/.gm/prd.yml','utf8'));
const mutPath = 'C:/dev/deepseek-harness/.gm/mutables.yml';
fs.writeFileSync(path.join(outDir, 'mutables.yml'), fs.existsSync(mutPath) ? fs.readFileSync(mutPath,'utf8') : '');
const extra = {
  phase: d.phase,
  next_phase_hint: d.next_phase_hint,
  prd_pending_count: d.prd_pending_count,
  mutables_pending_count: d.mutables_pending_count,
  should_residual_scan: d.should_residual_scan,
  sub_phase: d.sub_phase,
  epistemic_gap: d.epistemic_gap,
  keys: Object.keys(d),
  policy: d.policy || d.discipline_policies || null,
  gates: d.gates || d.fsm_gates || d.fsm_gates_weaker_than_default || null,
  prove: d.prove || d.phase_prose || null,
  ready_wave: d.ready_wave,
  prd_items: d.prd_items,
};
fs.writeFileSync(path.join(outDir, 'meta.json'), JSON.stringify(extra, null, 2));
console.log('wrote', {
  instr: (d.instruction||'').length,
  prd: fs.statSync(path.join(outDir,'prd.yml')).size,
  mut: fs.statSync(path.join(outDir,'mutables.yml')).size,
  keys: extra.keys,
});"}

