{"verb":"exec_js","session_id":"gmH2-1","cwd":"C:\dev\deepseek-harness","raw_body":"timeoutMs=20000
const fs = require('fs');
const path = require('path');
const {execSync, spawnSync} = require('child_process');
const os = require('os');

function tryExec(cmd, opts={}) {
  try {
    const out = execSync(cmd, {encoding:'utf8', timeout: opts.timeout || 8000, stdio:['ignore','pipe','pipe'], ...opts});
    return {ok:true, out: String(out).slice(0,4000)};
  } catch (e) {
    return {ok:false, err: String(e.stderr||e.message).slice(0,1500), status: e.status};
  }
}

const envKeys = Object.keys(process.env).filter(k => /FREDDIE|GM|DEEPSEEK|SESSION/i.test(k)).sort();
const env = {};
for (const k of envKeys) {
  const v = process.env[k] || '';
  env[k] = v.length > 200 ? v.slice(0,200)+'...' : v;
}

const pid = process.pid;
let parent = null;
try {
  const wmi = execSync(`wmic process where ProcessId=${pid} get ParentProcessId,Name,CommandLine /FORMAT:LIST`, {encoding:'utf8', timeout:8000});
  parent = wmi.slice(0,2000);
} catch (e) {
  parent = String(e.message).slice(0,500);
}

const ports = [3080,3087,4800,4801,4914,3000];
const http = {};
for (const p of ports) {
  try {
    const r = spawnSync('curl.exe', ['-sS','-m','2','-o','NUL','-w','%{http_code} %{errormsg}','http://127.0.0.1:'+p+'/'], {encoding:'utf8', timeout:4000});
    http[p] = {status:r.status, out:(r.stdout||'').slice(0,200), err:(r.stderr||'').slice(0,200)};
  } catch (e) {
    http[p] = {error: String(e.message).slice(0,200)};
  }
}

const home = process.env.FREDDIE_HOME || path.join(os.homedir(), '.freddie');
const sid = process.env.FREDDIE_SESSION_ID || null;
const jsonl = process.env.FREDDIE_SESSION_JSONL || null;

const listing = {
  cwd: process.cwd(),
  pid, ppid: process.ppid,
  node: process.version,
  platform: process.platform,
  env,
  parent,
  http,
  home,
  sid,
  jsonl,
  homeExists: fs.existsSync(home),
};

console.log(JSON.stringify(listing, null, 2));"}

