const fs = require('fs');
const path = require('path');

function walk(dir, acc, depth, pred) {
  if (depth > 5) return;
  let ents; try { ents = fs.readdirSync(dir, {withFileTypes:true}); } catch { return; }
  for (const e of ents) {
    if (e.name === 'node_modules' || e.name === '.git' || e.name === '.gm') continue;
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walk(p, acc, depth+1, pred);
    else if (pred(e.name, p)) acc.push(p);
  }
}

const hits = [];
walk('C:/dev/deepseek-harness/packages', hits, 0, (n,p) => /zstd/i.test(n) || n === 'package.json');
const zstdFiles = hits.filter(p => /zstd/i.test(p));
const persistPkgs = [];
for (const p of hits.filter(p => p.endsWith('package.json'))) {
  const t = fs.readFileSync(p,'utf8');
  if (/zstd|fzstd|compress/.test(t) || /session-persistence/.test(p)) {
    persistPkgs.push({p, snippet: t.slice(0,400)});
  }
}

console.log(JSON.stringify({zstdFiles, persistPkgs: persistPkgs.map(x => x.p)}, null, 2));
