const fs = require('fs');
const {spawnSync} = require('child_process');

function wmic(filter) {
  const r = spawnSync('wmic.exe', ['process', 'where', filter, 'get', 'ProcessId,ParentProcessId,Name,CommandLine', '/FORMAT:LIST'], {encoding:'utf8', timeout:15000, windowsHide:true, maxBuffer: 8*1024*1024});
  return {status:r.status, err:(r.stderr||'').slice(0,400), out:(r.stdout||'')};
}

const node = wmic("Name='node.exe'");
const lines = (node.out||'').split(/\r?\n/);
const procs = [];
let cur = {};
for (const line of lines) {
  const m = line.match(/^(CommandLine|Name|ParentProcessId|ProcessId)=(.*)$/);
  if (m) {
    cur[m[1]] = m[2];
    if (m[1] === 'ProcessId' && cur.CommandLine) {
      const cl = cur.CommandLine;
      if (/freddie|deepseek-harness|apps\/cli|headless|gm-mcp|acptoapi/i.test(cl)) {
        procs.push({...cur, CommandLine: cl.slice(0,500)});
      }
      cur = {};
    }
  }
}

const ports = {};
const net = spawnSync('netstat.exe', ['-ano'], {encoding:'utf8', timeout:10000, windowsHide:true, maxBuffer: 8*1024*1024});
const want = new Set(['3080','3087','4800','3000','4914']);
for (const line of (net.stdout||'').split(/\r?\n/)) {
  const m = line.match(/TCP\s+\S+:(\d+)\s+\S+\s+(\S+)\s+(\d+)/);
  if (m && want.has(m[1])) {
    (ports[m[1]] ||= []).push({state:m[2], pid:m[3]});
